 "content": "def transform(grid):
    # Demonstrations imply the lower figure is translated to rows 3-5;
    # the rightmost upper figure sits above it with a one-row gap.
    w = len(grid[0])
    divider = next(r for r, row in enumerate(grid) if all(x == 5 for x in row))
    upper, lower = grid[:divider], grid[divider + 1:]
    objects = {}
    for r, row in enumerate(upper):
        for c, value in enumerate(row):
            if value not in (0, 2, 5):
                objects.setdefault(value, []).append((r, c))
    color = max(objects, key=lambda value: max(c for r, c in objects[value]))
    motif = objects[color]
    base = [(r, c) for r, row in enumerate(lower) for c, value in enumerate(row) if value == 1]

    out = [[0] * w for _ in range(9)]
    min_base_r = min(r for r, c in base)
    for r, c in base:
        out[r - min_base_r + 3][c] = 1

    min_mr, max_mr = min(r for r, c in motif), max(r for r, c in motif)
    min_mc, max_mc = min(c for r, c in motif), max(c for r, c in motif)
    min_bc, max_bc = min(c for r, c in base), max(c for r, c in base)
    shift_c = round((min_bc + max_bc - min_mc - max_mc) / 2)
    motif_top = 3 - (max_mr - min_mr + 1) - 1
    for r, c in motif:
        rr, cc = motif_top + r - min_mr, c + shift_c
        if 0 <= rr < 9 and 0 <= cc < w:
            out[rr][cc] = color
    return out

if __name__ == '__main__':
